        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Accise, il decreto effimero",
        "testo_it": "Il governo italiano proroga il taglio delle accise sui carburanti fino al 6 giugno per contrastare il caro-prezzi.",
        "priorita": "Bassa",
        "id_gruppo": 19,
        "link": "https://ilmanifesto.it/accise-il-decreto-effimero-2",
        "orario": "00:07",
